                    item.classList.add('al-active');
                });
            });
        });

        // 牌子多選邏輯
        const brandItems = container.querySelectorAll('.al-brand-item');
        brandItems.forEach(item => {
            item.addEventListener('click', () => {
                if (item.innerText.trim() !== "") {
                    item.classList.toggle('al-active');
                }
            });
        });

