            exportBtn.innerHTML = '圖片生成中...';
            exportBtn.disabled = true;

            loadHtml2Canvas(() => {
                const captureElement = container.querySelector('#ask-list-capture-area');
                window.html2canvas(captureElement, {
                    scale: 2, // 高清輸出
                    backgroundColor: '#0f172a', // 配合暗黑主題的背景底色
                    useCORS: true
                }).then(canvas => {
                    const link = document.createElement('a');
                    link.download = 'My-PC-List.png';
                    link.href = canvas.toDataURL('image/png');
                    link.click();

                    exportBtn.innerHTML = originalText;
                    exportBtn.disabled = false;
                }).catch(err => {
                    console.error('導出失敗:', err);
                    alert('導出圖片時發生錯誤，請檢查瀏覽器權限。');
                    exportBtn.innerHTML = originalText;
                    exportBtn.disabled = false;
                });
            });
        });

    } catch (err) {
        console.error("Ask-List Form Render Error:", err);
    }
