            ["萬麗 Manli", "Gallardo (蓋拉多)", "NVIDIA", "T3 主流性價比", "軍綠/黑色外觀 / 雙水準儀(早期特徵)", "老牌代工廠，市面少見的「通路丐王」高性價比", ["Manli", "NVIDIA", "T3 主流性價比"], 0],
            ["麗台 Leadtek", "WinFast / Hurricane", "NVIDIA", "T3 主流性價比", "渦輪扇(早期) / 雙風扇基礎版", "主要專注於繪圖卡(Quadro/RTX)，遊戲卡多為公版換皮", ["Leadtek", "NVIDIA", "T3 主流性價比"], 0]
        ];

        let selectedTags = new Set();
        let currentPage = 1;
        const PAGE_SIZE = 15;

        // 注入 CSS 樣式
        const styleId = 'gpu-tier-modern-style';
        if (!document.getElementById(styleId)) {
            const style = document.createElement('style');
            style.id = styleId;
            style.innerHTML = `
