                .gt-btn.active-amd { background-color: #ef4444; border-color: #f87171; box-shadow: 0 0 8px rgba(239,68,68,0.5); }
                .gt-btn.active-intel { background-color: #0ea5e9; border-color: #38bdf8; box-shadow: 0 0 8px rgba(14,165,233,0.5); }
