                }
                th:nth-child(1) { width: 10%; } /* 品牌 */
                th:nth-child(2) { width: 16%; } /* 系列名稱 */
                th:nth-child(3) { width: 10%; } /* 晶片陣營 */
                th:nth-child(4) { width: 12%; } /* 階級定位 */
                th:nth-child(5) { width: 24%; } /* 特徵 */
                th:nth-child(6) { width: 28%; } /* 評價 */

