                tr.highlight-row { background-color: #311847; }

                .tag-nvidia { color: #4ade80; font-weight: 800; }
                .tag-amd { color: #f87171; font-weight: 800; }
                .tag-intel { color: #38bdf8; font-weight: 800; }
                .tag-t0 { color: #c084fc; font-weight: 900; background: rgba(192,132,252,0.1); padding:2px 4px; border-radius:4px; }
                .tag-t1 { color: #fca5a5; font-weight: 800; }
                .tag-t2 { color: #fcd34d; font-weight: 700; }
                .tag-t3 { color: #e2e8f0; font-weight: 600; }
                .tag-t4 { color: #94a3b8; font-weight: 500; }

                .gt-footer {
                    display: flex;
