            document.head.appendChild(style);
        }

        const container = document.createElement('div');
        container.className = 'gpu-tier-container';
        element.appendChild(container);

        function render() {
            const L = I18N_GPU_TIER[lang];
            const query = container.querySelector('.gt-search-input') ? container.querySelector('.gt-search-input').value.trim().toLowerCase() : '';
            const activeTagsArr = Array.from(selectedTags).map(t => t.toLowerCase());

            // 過濾數據
            const filteredRows = GPU_SERIES_DATA.filter(r => {
                const rowTags = (r[6] || []).map(t => t.toLowerCase());
                const text = r.join(' ').toLowerCase();
                const matchAllTags = activeTagsArr.every(selected => rowTags.includes(selected));
                const matchQuery = !query || text.includes(query);
                return matchAllTags && matchQuery;
            });

            const totalCount = filteredRows.length;
            const totalPages = Math.ceil(totalCount / PAGE_SIZE) || 1;
            if (currentPage > totalPages) currentPage = 1;
            const startIdx = (currentPage - 1) * PAGE_SIZE;
            const currentRows = filteredRows.slice(startIdx, startIdx + PAGE_SIZE);

            // 構建按鈕函數
            function buildBtn(tag, customClass = '') {
                const isActive = selectedTags.has(tag);
                let btnClass = 'gt-btn';
                if (isActive) {
                    if (tag === 'NVIDIA') btnClass += ' active-nv';
                    else if (tag === 'AMD') btnClass += ' active-amd';
                    else if (tag === 'Intel') btnClass += ' active-intel';
                    else btnClass += ' active';
                }
                const checkIcon = isActive ? "✓ " : "";
                return `<button type="button" class="${btnClass}" data-tag="${tag}">${checkIcon}${tag}</button>`;
            }

            const resetBtnHTML = selectedTags.size > 0 
                ? `<button type="button" class="gt-btn gt-btn-reset">${L.resetBtn} (${selectedTags.size})</button>` : '';

            // 渲染表格內容
            const tbodyHTML = currentRows.map((r) => {
                const isHalo = r[7] === 1;
                const rowClass = isHalo ? 'highlight-row' : '';
                const star = isHalo ? '<span style="color:#eab308; margin-right:4px;">★</span>' : '';

                // 晶片陣營上色
                let campHtml = r[2];
                campHtml = campHtml.replace('NVIDIA', '<span class="tag-nvidia">NVIDIA</span>');
                campHtml = campHtml.replace('AMD', '<span class="tag-amd">AMD</span>');
                campHtml = campHtml.replace('Intel', '<span class="tag-intel">Intel</span>');

                // 階級上色
                let tierHtml = r[3];
                if (tierHtml.includes('T0')) tierHtml = `<span class="tag-t0">${tierHtml}</span>`;
                else if (tierHtml.includes('T1')) tierHtml = `<span class="tag-t1">${tierHtml}</span>`;
                else if (tierHtml.includes('T2')) tierHtml = `<span class="tag-t2">${tierHtml}</span>`;
                else if (tierHtml.includes('T3')) tierHtml = `<span class="tag-t3">${tierHtml}</span>`;
                else if (tierHtml.includes('T4')) tierHtml = `<span class="tag-t4">${tierHtml}</span>`;

                return `
                    <tr class="${rowClass}">
                        <td style="font-weight:bold; color:#e2e8f0;">${r[0]}</td>
                        <td style="font-size:13.5px; font-weight:800; color:#fff;">${star}${r[1]}</td>
                        <td>${campHtml}</td>
                        <td>${tierHtml}</td>
                        <td style="color:#cbd5e1;">${r[4]}</td>
                        <td style="color:#94a3b8;">${r[5]}</td>
                    </tr>
                `;
            }).join('') || `<tr><td colspan="6" style="text-align:center; padding:40px;">${L.noMatch}</td></tr>`;

            container.innerHTML = `
                <div class="gt-wrapper">
                    <div class="gt-header-box">
                        <div>
                            <div class="gt-title">${L.title}</div>
                            <div class="gt-subtitle">${L.subTitle}</div>
                        </div>
                        <div style="display:flex; gap:10px; align-items:center;">
                            <input type="text" class="gt-search-input" value="${query}" placeholder="${L.searchPlaceholder}" style="padding:6px 12px; border-radius:6px; border:1px solid #475569; background:#0f172a; color:#fff; font-size:12px; outline:none; width:220px;">
                        </div>
                    </div>

                    <div class="gt-filter-panel">
                        <div class="gt-filter-row">
                            <span class="gt-filter-label">${L.gpuLabel}</span>
                            ${buildBtn('NVIDIA')} ${buildBtn('AMD')} ${buildBtn('Intel')}
                            <span style="margin-left:10px;">${resetBtnHTML}</span>
                        </div>
                        <div class="gt-filter-row">
                            <span class="gt-filter-label">${L.tierLabel}</span>
                            ${buildBtn('T0 限量神檯')} ${buildBtn('T1 頂級旗艦')} ${buildBtn('T2 高階中堅')} ${buildBtn('T3 主流性價比')} ${buildBtn('T4 入門亮機')}
                        </div>
                        <div class="gt-filter-row" style="margin-top:6px; padding-top:6px; border-top:1px dashed #334155;">
                            <span class="gt-filter-label">${L.vendorLabel}</span>
                            ${buildBtn('ASUS')} ${buildBtn('MSI')} ${buildBtn('GIGABYTE')} ${buildBtn('COLORFUL')}
                            ${buildBtn('ZOTAC')} ${buildBtn('GALAX')} ${buildBtn('INNO3D')} ${buildBtn('PALIT')} ${buildBtn('PNY')}
                            ${buildBtn('SAPPHIRE')} ${buildBtn('POWERCOLOR')} ${buildBtn('ASROCK')} ${buildBtn('XFX')}
                        </div>
                    </div>

                    <div style="border: 1px solid #334155; border-radius: 8px; overflow: hidden;">
                        <table>
                            <thead>
                                <tr>
                                    ${L.headers.map(h => `<th>${h}</th>`).join('')}
                                </tr>
                            </thead>
                            <tbody>
                                ${tbodyHTML}
                            </tbody>
                        </table>
                    </div>

                    <div class="gt-footer">
                        <div>${L.pageInfo} <b style="color:#fff;">${totalCount === 0 ? 0 : startIdx + 1} - ${Math.min(startIdx + PAGE_SIZE, totalCount)}</b> ${L.ofTotal} <b style="color:#fff;">${totalCount}</b> ${L.modelsText}</div>
                        <div style="display:flex; gap:8px; align-items:center;">
                            <button class="gt-page-btn prev-btn" ${currentPage <= 1 ? 'disabled' : ''}>${L.prevPage}</button>
                            <span style="color:#e2e8f0; font-weight:bold;">${currentPage} / ${totalPages}</span>
                            <button class="gt-page-btn next-btn" ${currentPage >= totalPages ? 'disabled' : ''}>${L.nextPage}</button>
                        </div>
                    </div>
                </div>
            `;

            // 綁定事件
            container.querySelectorAll('.gt-btn[data-tag]').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    const tag = e.target.getAttribute('data-tag');
                    if (selectedTags.has(tag)) selectedTags.delete(tag);
                    else selectedTags.add(tag);
                    currentPage = 1;
                    render();
                });
            });

            const resetBtn = container.querySelector('.gt-btn-reset');
            if (resetBtn) {
                resetBtn.addEventListener('click', () => {
                    selectedTags.clear();
                    currentPage = 1;
                    render();
                });
            }

            const searchInput = container.querySelector('.gt-search-input');
            if (searchInput) {
                searchInput.addEventListener('input', () => {
                    currentPage = 1;
                    render();
                });
                // 保持焦點
                searchInput.focus();
                const val = searchInput.value;
                searchInput.value = '';
                searchInput.value = val;
            }

            const prevBtn = container.querySelector('.prev-btn');
            if (prevBtn) prevBtn.addEventListener('click', () => { if (currentPage > 1) { currentPage--; render(); } });

            const nextBtn = container.querySelector('.next-btn');
            if (nextBtn) nextBtn.addEventListener('click', () => { if (currentPage < totalPages) { currentPage++; render(); } });
        }

        render();

    } catch (err) {
        console.error("GPU Tier Matrix Render Error:", err);
    }
})();
